examples.setup:
val state = rememberMonarchRichTextEditorState()
val people = listOf(MonarchMentionItem(id = "u1", label = "Ana Lopez", detail = "Design"))
var suggestions by remember { mutableStateOf(emptyList<MonarchMentionItem>()) }

examples.code:
@OptIn(ExperimentalMonarchApi::class)
MonarchRichTextEditor(
    label = "Reply",
    state = state,
    prompt = "Reply to the thread",
    tools = MonarchEditorTool.InlineGroups,
    mentionItems = suggestions,
    onMentionSearch = { query ->
        suggestions = if (query == null) emptyList() else people.filter { it.label.contains(query.text, ignoreCase = true) }
    },
)
